"""Measure exact score-storage device work with CUDA graphs and no model forward."""
import json
import statistics
import sys
from pathlib import Path

import torch
from rich.console import Console

from compare_score_replay import MODES, RANK, SHAPES, make_store


def construct(mode, features, scores, weights):
    steps, batch, width = features.shape
    keepalive = []
    graph = torch.cuda.CUDAGraph()
    with torch.cuda.graph(graph):
        memory = make_store(mode, steps, batch, width)
        if mode == "chunk_accumulator":
            keepalive.extend((memory.features, memory.residuals))
        for index, (feature, score) in enumerate(zip(features.unbind(), scores.unbind(), strict=True)):
            memory.push(index, feature, score)
        memory.end()
        result = memory.reduce(weights)
    return graph, memory, result, keepalive


def main():
    torch.set_num_threads(1)
    torch.set_float32_matmul_precision("highest")
    torch.manual_seed(19257)
    measurements = {}
    with torch.inference_mode():
        for batch, steps in SHAPES:
            x = torch.randn((steps, batch, 1536), device="cuda", dtype=torch.bfloat16)
            y = torch.randn((steps, batch, RANK), device="cuda", dtype=torch.float32)
            weights = torch.linspace(-1.0, 1.0, batch, device="cuda")
            ideal = x.flatten(0, 1).double().T @ (y.double() * weights[None, :, None]).flatten(0, 1)
            # Prime the matmul library on the capture stream before any graph is captured.
            warm = torch.cuda.Stream()
            warm.wait_stream(torch.cuda.current_stream())
            with torch.cuda.stream(warm):
                for mode in MODES:
                    scratch = make_store(mode, steps, batch, 1536)
                    for idx, (feature, score) in enumerate(zip(x.unbind(), y.unbind(), strict=True)):
                        scratch.push(idx, feature, score)
                    scratch.end()
                    scratch.reduce(weights)
            torch.cuda.current_stream().wait_stream(warm)
            graphs = {mode: construct(mode, x, y, weights) for mode in MODES}
            torch.cuda.synchronize()
            for graph, _, result, _ in graphs.values():
                graph.replay()
                torch.testing.assert_close(result.double(), ideal, atol=3e-3, rtol=2e-5)
            cohort = {mode: [] for mode in MODES}
            for cohort_idx in range(8):
                for mode in MODES[cohort_idx % 4:] + MODES[:cohort_idx % 4]:
                    begin, end = torch.cuda.Event(enable_timing=True), torch.cuda.Event(enable_timing=True)
                    begin.record()
                    for _ in range(12):
                        graphs[mode][0].replay()
                    end.record()
                    end.synchronize()
                    cohort[mode].append(begin.elapsed_time(end) / 12)
            measurements[f"{batch}x{steps}"] = {mode: {"round_device_ms": values, "median_device_ms": statistics.median(values)}
                                                   for mode, values in cohort.items()}
    record = {"scope": "Synthetic BF16 features and FP32 residuals already on device. Timed CUDA graph only, including collection and reduction. No model, Python launch costs, allocation at replay time, or live-rollout gate.",
              "graph_repeats_per_observation": 12, "gpu": torch.cuda.get_device_name(), "measurements": measurements}
    Console().print_json(data={shape: {mode: row["median_device_ms"] for mode, row in scores.items()}
                               for shape, scores in measurements.items()})
    with Path(sys.argv[1]).open("x", encoding="utf-8") as output:
        json.dump(record, output, sort_keys=True, allow_nan=False)


if __name__ == "__main__":
    main()

